create type public.notification_type as enum ('APPOINTMENT_BOOKED','APPOINTMENT_CONFIRMED','APPOINTMENT_CANCELLED','TEST_BOOKED','COLLECTION_ASSIGNED','SAMPLE_COLLECTED','SAMPLE_DELIVERED','REPORT_READY','FOLLOW_UP_REMINDER');
create table public.notifications (id uuid primary key default gen_random_uuid(), recipient_user_id uuid not null references public.users(id) on delete cascade, notification_type public.notification_type not null, title text not null, body text not null, resource_type text, resource_id uuid, dedupe_key text not null unique, read_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint notifications_title_nonempty check (length(trim(title)) > 0), constraint notifications_body_nonempty check (length(trim(body)) > 0));
create index notifications_recipient_created_idx on public.notifications (recipient_user_id, created_at desc); create index notifications_unread_idx on public.notifications (recipient_user_id, read_at, created_at desc); alter table public.notifications enable row level security;
create or replace function public.set_notification_updated_at() returns trigger language plpgsql security invoker set search_path = public as $$ begin new.updated_at = now(); return new; end; $$; drop trigger if exists notifications_set_updated_at on public.notifications; create trigger notifications_set_updated_at before update on public.notifications for each row execute function public.set_notification_updated_at();
create or replace function public.prevent_notification_content_change() returns trigger language plpgsql security invoker set search_path = public as $$ begin if new.recipient_user_id <> old.recipient_user_id or new.notification_type <> old.notification_type or new.title <> old.title or new.body <> old.body or new.resource_type is distinct from old.resource_type or new.resource_id is distinct from old.resource_id or new.dedupe_key <> old.dedupe_key or new.created_at <> old.created_at then raise exception using errcode = '42501', message = 'Notification content is immutable'; end if; return new; end; $$; drop trigger if exists notifications_prevent_content_change on public.notifications; create trigger notifications_prevent_content_change before update on public.notifications for each row execute function public.prevent_notification_content_change();
create policy notifications_select_recipient on public.notifications for select to authenticated using (recipient_user_id = auth.uid()); create policy notifications_update_recipient on public.notifications for update to authenticated using (recipient_user_id = auth.uid()) with check (recipient_user_id = auth.uid());
create or replace function public.mark_notification_read(p_notification_id uuid) returns public.notifications language plpgsql security definer set search_path = public as $$ declare v_notification public.notifications; begin if auth.uid() is null then raise exception using errcode = '42501', message = 'Authentication required'; end if; update public.notifications set read_at = coalesce(read_at, now()) where id = p_notification_id and recipient_user_id = auth.uid() returning * into v_notification; if v_notification.id is null then raise exception using errcode = '42501', message = 'Notification not found or access denied'; end if; return v_notification; end; $$;
create or replace function public.mark_all_notifications_read() returns integer language plpgsql security definer set search_path = public as $$ declare v_count integer; begin if auth.uid() is null then raise exception using errcode = '42501', message = 'Authentication required'; end if; update public.notifications set read_at = coalesce(read_at, now()) where recipient_user_id = auth.uid() and read_at is null; get diagnostics v_count = row_count; return v_count; end; $$; revoke all on function public.mark_notification_read(uuid) from public; grant execute on function public.mark_notification_read(uuid) to authenticated; revoke all on function public.mark_all_notifications_read() from public; grant execute on function public.mark_all_notifications_read() to authenticated;
create or replace function public.insert_notification(p_recipient_user_id uuid, p_notification_type public.notification_type, p_title text, p_body text, p_resource_type text, p_resource_id uuid, p_dedupe_key text) returns void language plpgsql security definer set search_path = public as $$ begin if p_recipient_user_id is null then return; end if; insert into public.notifications (recipient_user_id, notification_type, title, body, resource_type, resource_id, dedupe_key) values (p_recipient_user_id, p_notification_type, p_title, p_body, p_resource_type, p_resource_id, p_dedupe_key) on conflict (dedupe_key) do nothing; end; $$; revoke all on function public.insert_notification(uuid, public.notification_type, text, text, text, uuid, text) from public;
create or replace function public.notify_appointment_event() returns trigger language plpgsql security definer set search_path = public as $$ declare v_patient_user_id uuid; v_doctor_user_id uuid; begin select p.user_id into v_patient_user_id from public.patients p where p.id = new.patient_id; select u.id into v_doctor_user_id from public.doctors d join public.users u on u.id = d.user_id where d.id = new.doctor_id; if tg_op = 'INSERT' then perform public.insert_notification(v_patient_user_id, 'APPOINTMENT_BOOKED', 'Appointment booked', 'Your appointment has been booked.', 'appointment', new.id, 'appointment:' || new.id::text || ':booked'); perform public.insert_notification(v_doctor_user_id, 'APPOINTMENT_BOOKED', 'New appointment', 'A patient appointment has been booked.', 'appointment', new.id, 'appointment:' || new.id::text || ':booked:doctor'); elsif new.status is distinct from old.status then if new.status = 'confirmed' then perform public.insert_notification(v_patient_user_id, 'APPOINTMENT_CONFIRMED', 'Appointment confirmed', 'Your appointment has been confirmed.', 'appointment', new.id, 'appointment:' || new.id::text || ':confirmed'); elsif new.status = 'cancelled' then perform public.insert_notification(v_patient_user_id, 'APPOINTMENT_CANCELLED', 'Appointment cancelled', 'Your appointment has been cancelled.', 'appointment', new.id, 'appointment:' || new.id::text || ':cancelled'); perform public.insert_notification(v_doctor_user_id, 'APPOINTMENT_CANCELLED', 'Appointment cancelled', 'An appointment has been cancelled.', 'appointment', new.id, 'appointment:' || new.id::text || ':cancelled:doctor'); end if; end if; return new; end; $$; create trigger appointments_notify_event after insert or update of status on public.appointments for each row execute function public.notify_appointment_event();
create or replace function public.notify_test_order_event() returns trigger language plpgsql security definer set search_path = public as $$ declare v_patient_user_id uuid; v_doctor_user_id uuid; begin select p.user_id into v_patient_user_id from public.patients p where p.id = new.patient_id; if new.doctor_id is not null then select u.id into v_doctor_user_id from public.doctors d join public.users u on u.id = d.user_id where d.id = new.doctor_id; end if; perform public.insert_notification(v_patient_user_id, 'TEST_BOOKED', 'Diagnostic test booked', 'Your diagnostic test order has been created.', 'test_order', new.id, 'test_order:' || new.id::text || ':booked'); perform public.insert_notification(v_doctor_user_id, 'TEST_BOOKED', 'Diagnostic test ordered', 'A diagnostic test order is linked to your patient.', 'test_order', new.id, 'test_order:' || new.id::text || ':doctor'); return new; end; $$; create trigger test_orders_notify_event after insert on public.test_orders for each row execute function public.notify_test_order_event();
create or replace function public.notify_collection_assignment() returns trigger language plpgsql security definer set search_path = public as $$ declare v_patient_user_id uuid; v_agent_user_id uuid; begin if new.collection_agent_id is not null and (tg_op = 'INSERT' or new.collection_agent_id is distinct from old.collection_agent_id) then select p.user_id into v_patient_user_id from public.patients p where p.id = new.patient_id; select u.id into v_agent_user_id from public.collection_agents a join public.users u on u.id = a.user_id where a.id = new.collection_agent_id; perform public.insert_notification(v_agent_user_id, 'COLLECTION_ASSIGNED', 'Collection assigned', 'A home sample collection request has been assigned to you.', 'collection_request', new.id, 'collection:' || new.id::text || ':assigned:agent'); perform public.insert_notification(v_patient_user_id, 'COLLECTION_ASSIGNED', 'Collection agent assigned', 'A collection agent has been assigned to your request.', 'collection_request', new.id, 'collection:' || new.id::text || ':assigned:patient'); end if; return new; end; $$; create trigger collection_requests_notify_assignment after insert or update of collection_agent_id on public.collection_requests for each row execute function public.notify_collection_assignment();
create or replace function public.notify_sample_event() returns trigger language plpgsql security definer set search_path = public as $$ declare v_patient_user_id uuid; begin if new.status is distinct from old.status and new.status in ('COLLECTED','DELIVERED') then select p.user_id into v_patient_user_id from public.patients p join public.test_orders o on o.patient_id = p.id where o.id = new.test_order_id; if new.status = 'COLLECTED' then perform public.insert_notification(v_patient_user_id, 'SAMPLE_COLLECTED', 'Sample collected', 'Your diagnostic sample has been collected.', 'sample', new.id, 'sample:' || new.id::text || ':collected'); elsif new.status = 'DELIVERED' then perform public.insert_notification(v_patient_user_id, 'SAMPLE_DELIVERED', 'Sample delivered', 'Your sample has been delivered to the laboratory.', 'sample', new.id, 'sample:' || new.id::text || ':delivered'); end if; end if; return new; end; $$; create trigger samples_notify_event after update of status on public.samples for each row execute function public.notify_sample_event();
create or replace function public.notify_report_event() returns trigger language plpgsql security definer set search_path = public as $$ declare v_patient_user_id uuid; begin select p.user_id into v_patient_user_id from public.patients p where p.id = new.patient_id; perform public.insert_notification(v_patient_user_id, 'REPORT_READY', 'Report ready', 'A medical report is now available in your records.', 'medical_report', new.id, 'report:' || new.id::text || ':ready'); return new; end; $$; create trigger medical_reports_notify_event after insert on public.medical_reports for each row execute function public.notify_report_event();
create or replace function public.notify_follow_up_event() returns trigger language plpgsql security definer set search_path = public as $$ declare v_patient_user_id uuid; begin if new.follow_up_date is not null then select p.user_id into v_patient_user_id from public.patients p where p.id = new.patient_id; perform public.insert_notification(v_patient_user_id, 'FOLLOW_UP_REMINDER', 'Follow-up reminder', 'Your clinician scheduled a follow-up for ' || new.follow_up_date::text || '.', 'consultation', new.id, 'consultation:' || new.id::text || ':follow-up'); end if; return new; end; $$; create trigger consultations_notify_follow_up after insert on public.consultations for each row execute function public.notify_follow_up_event();
